-- C-04: financial creditors, related companies and their subsidiary assignments.
set local lock_timeout='5s';set local statement_timeout='60s';
create schema financial_entity_master_private;revoke all on schema financial_entity_master_private from public,anon,authenticated,service_role;
create or replace function organization_master_private.meta(k text)returns table(t text,pk text,links text,fields text[])language sql immutable set search_path=pg_catalog as $$select c.t,c.pk,c.links,c.fields from(values
 ('departments','departments','department_id','department_subsidiaries',array['name','type','parent_id','is_inactive']),
 ('locations','locations','location_id','location_subsidiaries',array['name','parent_id','country_id']),
 ('classes','classes','class_id','class_subsidiaries',array['name','parent_id','description','is_inactive']),
 ('cost-centers','cost_centers','cost_center_id',null,array['name','subsidiary_id','cost_center_type','customer_id','department_id','class_id','up_approver_id']),
 ('financial-creditors','financial_creditors','financial_creditor_id','financial_creditor_subsidiaries',array['name','identification','is_inactive']),
 ('related-companies','related_companies','related_company_id','related_company_subsidiaries',array['name','identification','is_inactive','country_id']))c(k,t,pk,links,fields)where c.k=$1$$;
create function financial_entity_master_private.options(k text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare refs jsonb;begin perform organization_master_private.access(k,'view');
 refs:=jsonb_build_object('organization/subsidiaries',coalesce((select jsonb_agg(jsonb_build_object('subsidiary_id',s.subsidiary_id,'name',s.name))from public.subsidiaries s join public.user_subsidiaries us using(subsidiary_id)where us.user_id=public.app_user_id()and s.is_active),'[]'));
 if k='related-companies'then refs:=refs||jsonb_build_object('core/countries',coalesce((select jsonb_agg(jsonb_build_object('country_id',c.country_id,'name',c.name))from public.countries c),'[]'));end if;
 return jsonb_build_object('canView',true,'canCreate',organization_master_private.allowed(k,'create'),'canEdit',organization_master_private.allowed(k,'edit'),'canDelete',organization_master_private.allowed(k,'delete'),'references',refs);end$$;
create function financial_entity_master_private.save(k text,p jsonb,id bigint)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare c record;sid bigint;oldrow jsonb;data jsonb;r jsonb;subs bigint[];oldsubs bigint[];field text;cols text;vals text;sets text;used boolean;begin
 sid:=organization_master_private.access(k,case when id is null then'create'else'edit'end);select *into c from organization_master_private.meta(k);
 if k not in('financial-creditors','related-companies')or id<=0 or id>9007199254740991 or jsonb_typeof(p)is distinct from'object'or pg_column_size(p)>32000 or exists(select 1 from jsonb_object_keys(p)x where not x=any(c.fields||array['subsidiary_ids','_revision']))then raise exception using errcode='22023',message='Campos de entidad financiera inválidos.';end if;
 perform pg_advisory_xact_lock(793149,1);perform pg_advisory_xact_lock(793147,1);
 if id is not null then execute format('select to_jsonb(x)from public.%I x where %I=$1 for update',c.t,c.pk)into oldrow using id;if oldrow is null or not organization_master_private.visible(k,id)or not organization_master_private.writable(k,id)then raise exception using errcode='42501',message='Entidad compartida no autorizada para mantenimiento.';end if;if p->>'_revision'is distinct from organization_master_private.fingerprint(k,id)then raise exception using errcode='55000',message='La entidad cambió. Consúltela nuevamente.';end if;end if;
 subs:=entity_master_private.ids(p->'subsidiary_ids');if not sid=any(subs)or exists(select 1 from unnest(subs)x where not exists(select 1 from public.subsidiaries s join public.user_subsidiaries us using(subsidiary_id)where s.subsidiary_id=x and s.is_active and us.user_id=public.app_user_id()))then raise exception using errcode='42501',message='Seleccione filiales activas autorizadas incluyendo la actual.';end if;
 data:=coalesce(oldrow,jsonb_build_object('is_inactive',false))||(p-'subsidiary_ids'-'_revision');
 foreach field in array array['name','identification']loop if jsonb_typeof(data->field)is distinct from'string'or nullif(btrim(data->>field),'')is null or length(btrim(data->>field))>(case field when'name'then 250 else 100 end)then raise exception using errcode='22023',message='Nombre o identificación inválidos.';end if;data:=jsonb_set(data,array[field],to_jsonb(btrim(data->>field)));end loop;
 if jsonb_typeof(data->'is_inactive')is distinct from'boolean'then raise exception using errcode='22023',message='La opción de estado debe ser booleana.';end if;
 if k='related-companies'then if coalesce(data->>'country_id','')!~'^[1-9][0-9]{0,15}$'or(data->>'country_id')::numeric>9007199254740991 then raise exception using errcode='22023',message='País inválido.';end if;if not exists(select 1 from public.countries where country_id=(data->>'country_id')::bigint)then raise exception using errcode='42501',message='País no disponible.';end if;end if;
 if id is not null then oldsubs:=organization_master_private.scope_ids(k,id);used:=organization_master_private.used(k,id);if used and(not oldsubs<@subs or(oldrow->>'subsidiary_id')::bigint is distinct from subs[1]or oldrow->>'identification'is distinct from data->>'identification'or(k='related-companies'and oldrow->>'country_id'is distinct from data->>'country_id')or(not coalesce((oldrow->>'is_inactive')::boolean,false)and(data->>'is_inactive')::boolean))then raise exception using errcode='55000',message='La entidad utilizada conserva origen, identificación, país y asignaciones.';end if;end if;
 data:=data||jsonb_build_object('subsidiary_id',subs[1]);
 select string_agg(format('%I',x),','),string_agg(format('v.%I',x),','),string_agg(format('%I=v.%I',x,x),',')into cols,vals,sets from unnest(c.fields||array['subsidiary_id'])x;
 if id is null then execute format('insert into public.%I(%s)select %s from jsonb_populate_record(null::public.%I,$1)v returning to_jsonb(%I.*)',c.t,cols,vals,c.t,c.t)into r using data;id:=(r->>c.pk)::bigint;
 else execute format('update public.%I x set %s from jsonb_populate_record(null::public.%I,$1)v where x.%I=$2 returning to_jsonb(x)',c.t,sets,c.t,c.pk)into r using data,id;end if;
 execute format('delete from public.%I where %I=$1 and not subsidiary_id=any($2)',c.links,c.pk)using id,subs;
 execute format('insert into public.%I(%I,subsidiary_id)select $1,x from unnest($2::bigint[])x where not exists(select 1 from public.%I where %I=$1 and subsidiary_id=x)',c.links,c.pk,c.links,c.pk)using id,subs;
 return organization_master_private.dto(k,id);end$$;
create or replace function public.organization_master_options(p_catalog text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_catalog in('financial-creditors','related-companies')then return financial_entity_master_private.options(p_catalog);elsif p_catalog='cost-centers'then return cost_center_master_private.options();end if;return organization_master_private.organization_master_options(p_catalog);end$$;
create or replace function public.save_organization_master(p_catalog text,p_payload jsonb,p_id bigint default null)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_catalog in('financial-creditors','related-companies')then return financial_entity_master_private.save(p_catalog,p_payload,p_id);elsif p_catalog='cost-centers'then return cost_center_master_private.save(p_payload,p_id);end if;return organization_master_private.save_organization_master(p_catalog,p_payload,p_id);end$$;
do $$declare t text;k text;pk text;p record;col record;begin foreach t in array array['financial_creditors','financial_creditor_subsidiaries','related_companies','related_company_subsidiaries']loop
 k:=case when t like'financial%'then'financial-creditors'else'related-companies'end;pk:=case k when'financial-creditors'then'financial_creditor_id'else'related_company_id'end;
 for p in select policyname from pg_policies where schemaname='public'and tablename=t loop execute format('drop policy %I on public.%I',p.policyname,t);end loop;execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
 for col in select column_name from information_schema.columns where table_schema='public'and table_name=t loop execute format('revoke insert(%I),update(%I),select(%I),references(%I)on public.%I from public,anon,authenticated,service_role',col.column_name,col.column_name,col.column_name,col.column_name,t);end loop;
 execute format('create policy financial_entity_master_read on public.%I for select to authenticated using(organization_master_private.visible(%L,%I)%s)',t,k,pk,case when t like'%subsidiaries'then'and subsidiary_id=public.active_subsidiary_id()'else''end);execute format('grant select on public.%I to authenticated',t);end loop;end$$;
revoke all on all functions in schema financial_entity_master_private from public,anon,authenticated,service_role;
revoke all on function public.organization_master_list(text),public.organization_master_options(text),public.save_organization_master(text,jsonb,bigint),public.delete_organization_master(text,bigint,text)from public,anon,authenticated,service_role;
grant execute on function public.organization_master_list(text),public.organization_master_options(text),public.save_organization_master(text,jsonb,bigint),public.delete_organization_master(text,bigint,text)to authenticated;
notify pgrst,'reload schema';
